package com.tce.smart.platform.service.print;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import com.tce.smart.platform.api.dto.req.print.*;
import com.tce.smart.platform.core.mapper.PrintTemplateMapper;
import org.junit.*;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.Assert.*;
import static com.tce.smart.platform.service.print.PrintAccessPolicyTest.*;
/** 真实人员授权适配与真实Node业务PDF链路，只使用隔离H2及合成人员。 */
public class PrintJobPreparationTest {
 PrintJobServiceTest fixture;ObjectNode subject;PrintJobPreparation preparation;PrintRendererClient renderer;boolean photoTemplate;
 @Before public void setup()throws Exception{fixture=new PrintJobServiceTest();fixture.setup();subject=PrintJson.object().put("parkId","1").put("subjectType","STAFF").put("subjectId","a").put("printItemType","STAFF_CARD").put("personType","EMPLOYEE").put("classificationCode","STAFF_DEFAULT").put("employeeGradeCode","g1").put("employeeGradeName","合成职级").put("employeeGradeSource","DHR").put("cardRegistrationVerified",true);subject.putObject("fields").put("staffName","FrozenAlpha").put("cardNo","synthetic-card");subject.putArray("resources");configure(new PrintRendererClient(properties(),fixture.access));}
 @After public void close(){if(fixture!=null)fixture.close();}
 void configure(PrintRendererClient client)throws Exception{renderer=client;String front=publish("FRONT"),back=publish("BACK");PrintTemplateResolver resolver=org.mockito.Mockito.mock(PrintTemplateResolver.class);org.mockito.Mockito.when(resolver.select(org.mockito.ArgumentMatchers.anyString(),org.mockito.ArgumentMatchers.any(),org.mockito.ArgumentMatchers.any())).thenReturn(PrintJson.object().put("frontTemplateVersionId",front).put("backTemplateVersionId",back));preparation=new PrintJobPreparation((park,type,id)->subject.deepCopy(),resolver,fixture.tx.records,renderer);fixture.jobs=new PrintJobService(fixture.mapper,fixture.access,fixture.tx,fixture.printers,preparation,fixture.execution);}
 String publish(String face)throws Exception{PrintTemplateRequest draft=fixture.f.draft(face);ObjectNode c=((ArrayNode)draft.getLayoutJson().path("schemas").get(0)).addObject().put("name","person").put("type","text").put("content","").put("width",70).put("height",14).put("fontName","NotoSansSC").put("fontSize",12);c.putObject("position").put("x",4).put("y",4);((ArrayNode)draft.getFieldSchemaJson().path("fields")).addObject().put("key","staffName").put("schemaName","person").put("required",true);if(photoTemplate){ObjectNode photo=((ArrayNode)draft.getLayoutJson().path("schemas").get(0)).addObject().put("name","portrait").put("type","image").put("width",10).put("height",10);photo.putObject("position").put("x",70).put("y",35);((ArrayNode)draft.getFieldSchemaJson().path("fields")).addObject().put("key","personPhoto").put("schemaName","portrait").put("required",true);}String template=(String)fixture.f.service.create("1",draft).get("templateId");PrintPublishRequest request=new PrintPublishRequest();request.setDraftRevision(0L);request.setDraftVersionId((String)fixture.f.service.detail(template).get("currentDraftVersionId"));return (String)fixture.f.service.publish(template,request,UUID.randomUUID().toString()).getData().get("templateVersionId");}
 @Test public void missingRegistrationAndSpoofedSourceAreHardFailures(){subject.put("cardRegistrationVerified",false);expectCode("PRINT_CARD_REGISTRATION_REQUIRED",()->fixture.create("a"));subject.put("cardRegistrationVerified",true).put("parkId","2");expectCode("PRINT_SCOPE_DENIED",()->fixture.create("a"));assertEquals(0,fixture.f.jdbc.queryForObject("SELECT COUNT(*) FROM SMT_PRINT_JOB",Integer.class).intValue());}
 @Test public void frozenFieldsGradeAndModeNeverFollowLaterSource(){String id=fixture.create("a");subject.put("employeeGradeCode","g2");((ObjectNode)subject.get("fields")).put("staffName","ChangedBeta");JsonNode stored=PrintJson.read(fixture.f.jdbc.queryForObject("SELECT SNAPSHOT_JSON FROM SMT_PRINT_JOB WHERE JOB_ID=?",String.class,id));assertEquals("g1",stored.path("employeeGradeCode").asText());assertEquals("FrozenAlpha",stored.at("/renderRequest/faceSources/0/resolvedInput/fields/staffName").asText());assertEquals("FrozenAlpha",stored.at("/renderRequest/faceSources/1/resolvedInput/fields/staffName").asText());assertEquals("MANUAL_DUPLEX",stored.at("/renderRequest/printMode").asText());String publicJson=PrintJson.canonical(fixture.jobs.detail(id));assertEquals("FrozenAlpha",PrintJson.tree(fixture.jobs.detail(id)).at("/subjectSummary/displayName").asText());assertFalse(publicJson.contains("synthetic-card"));assertFalse(publicJson.contains("schemas"));}
 @Test public void realNodePrintPdfUsesOnlyFrozenFieldsAfterRestart()throws Exception{
  Assume.assumeTrue(Boolean.getBoolean("print.renderer.live"));Path root=Paths.get("../../..").toAbsolutePath().normalize().resolve("smart-print-renderer");String token=UUID.randomUUID().toString()+UUID.randomUUID().toString();ProcessBuilder command=new ProcessBuilder("node","--input-type=module","-e","import {createRenderServer} from './src/server.mjs';const s=createRenderServer({token:process.env.PRINT_RENDERER_TOKEN,concurrency:1});s.listen(0,'127.0.0.1',()=>console.log(s.address().port));");command.directory(root.toFile());command.environment().put("PRINT_RENDERER_TOKEN",token);command.redirectError(ProcessBuilder.Redirect.INHERIT);Process process=command.start();ExecutorService reader=Executors.newSingleThreadExecutor();try{String port=reader.submit(()->new BufferedReader(new InputStreamReader(process.getInputStream())).readLine()).get(20,TimeUnit.SECONDS);PrintFeatureProperties props=properties();props.setRendererUrl("http://127.0.0.1:"+Integer.parseInt(port));props.setRendererToken(token);props.setRendererReadTimeoutMs(60000);photoTemplate=true;photo(0xff123456);configure(new PrintRendererClient(props,fixture.access));PrintJobRenderer previewArtifacts=new PrintJobRenderer(fixture.mapper,fixture.tx,renderer,fixture.execution);PrintJobPreviewService preview=new PrintJobPreviewService(fixture.mapper,fixture.access,fixture.tx,preparation,renderer,previewArtifacts);ObjectNode creation=fixture.request("a");Map<String,Object> previewed=preview.preview(creation);creation.put("previewId",(String)previewed.get("previewId"));String id=(String)fixture.jobs.create(creation,"live-confirmed").getData().get("jobId");photo(0xffabcdef);expectCode("PRINT_PREVIEW_STALE",()->fixture.jobs.create(creation,"live-photo-stale"));subject.put("employeeGradeCode","g2");((ObjectNode)subject.get("fields")).put("staffName","ChangedBeta");expectCode("PRINT_PREVIEW_STALE",()->fixture.jobs.create(creation,"live-fields-stale"));org.springframework.security.core.context.SecurityContextHolder.clearContext();PrintJobRenderer restarted=new PrintJobRenderer(fixture.mapper,fixture.tx,renderer,fixture.execution);restarted.render(id);restarted.render(id);fixture.manager();assertEquals("READY",fixture.jobs.detail(id).get("status"));byte[] pdf=fixture.jobs.artifact(id,"combined");try(org.apache.pdfbox.pdmodel.PDDocument doc=org.apache.pdfbox.pdmodel.PDDocument.load(pdf)){assertEquals(2,doc.getNumberOfPages());String text=new org.apache.pdfbox.text.PDFTextStripper().getText(doc);assertTrue(text.contains("FrozenAlpha"));assertFalse(text.contains("ChangedBeta"));}assertEquals(3,fixture.f.jdbc.queryForObject("SELECT COUNT(*) FROM SMT_PRINT_JOB_ARTIFACT WHERE OWNER_ID=?",Integer.class,id).intValue());assertEquals(0,fixture.f.jdbc.queryForObject("SELECT COUNT(*) FROM SMT_PRINT_ATTEMPT",Integer.class).intValue());assertEquals("READY",preview.detail(creation.path("previewId").asText()).get("status"));assertEquals("READY",previewed.get("status"));assertEquals(1,fixture.f.jdbc.queryForObject("SELECT COUNT(*) FROM SMT_PRINT_JOB",Integer.class).intValue());assertEquals(1,fixture.f.jdbc.queryForObject("SELECT COUNT(*) FROM SMT_PRINT_JOB_PREVIEW",Integer.class).intValue());String jobArtifact=fixture.f.jdbc.queryForObject("SELECT ARTIFACT_ID FROM SMT_PRINT_JOB_ARTIFACT WHERE OWNER_ID=? AND FACE='FRONT'",String.class,id);expectCode("PRINT_SCOPE_DENIED",()->preview.artifact((String)previewed.get("previewId"),jobArtifact));}finally{process.destroy();if(!process.waitFor(5,TimeUnit.SECONDS))process.destroyForcibly();reader.shutdownNow();}}
 void photo(int color)throws Exception{java.awt.image.BufferedImage image=new java.awt.image.BufferedImage(2,2,java.awt.image.BufferedImage.TYPE_INT_RGB);for(int x=0;x<2;x++)for(int y=0;y<2;y++)image.setRGB(x,y,color);ByteArrayOutputStream out=new ByteArrayOutputStream();javax.imageio.ImageIO.write(image,"png",out);subject.putArray("resources").addObject().put("bindingKey","personPhoto").put("mediaType","image/png").put("sha256",PrintJson.hashBytes(out.toByteArray())).put("bytesBase64",Base64.getEncoder().encodeToString(out.toByteArray()));}
 @Test public void incompatiblePrinterMediaRejectsBeforeJobPersistence(){ObjectNode patch=PrintJson.object().put("configRevision",0);patch.putObject("mediaSpec").put("widthMm",54).put("heightMm",86);fixture.printers.save(fixture.printer,patch,"incompatible-media");expectCode("PRINTER_MEDIA_MISMATCH",()->fixture.create("a"));assertEquals(0,fixture.f.jdbc.queryForObject("SELECT COUNT(*) FROM SMT_PRINT_JOB",Integer.class).intValue());}
}
